// Package schema embeds the published JSON Schemas of the .sklp contracts
// other than pipelines, generated by cmd/genschema from the structs their
// loaders decode into.
package schema

import "embed"

//go:embed *.schema.json
var files embed.FS

// Contracts names each schema by the contract it describes.
var Contracts = map[string]string{
	"deploy":        "deploy.schema.json",
	"deploy-root":   "deploy-root.schema.json",
	"image-watches": "image-watches.schema.json",
}

// Get returns the schema of contract, or false when there is none.
func Get(contract string) ([]byte, bool) {
	name, ok := Contracts[contract]
	if !ok {
		return nil, false
	}
	raw, err := files.ReadFile(name)
	return raw, err == nil
}
